// Sales report over a hard-coded list — every question answered with nested
// loops, temp lists, and flag variables.
// Run from the repo root:
//   dotnet run csharp/04-linq-pipeline/original.cs
//
// The numbers are right. But each question took ~15 lines of loop plumbing,
// none of it is testable, and the third block quietly duplicates the first's
// "have I already handled this one?" trick. This is js#36 (log-analyzer)
// energy, in C#.

var sales = new List<Sale>
{
    new Sale("Keyboard", "North", 90m),
    new Sale("Keyboard", "South", 120m),
    new Sale("Mouse",    "North", 40m),
    new Sale("Mouse",    "South", 55m),
    new Sale("Monitor",  "North", 250m),
    new Sale("Monitor",  "West",  300m),
    new Sale("Webcam",   "West",  80m),
    new Sale("Keyboard", "West",  110m),
};

// ---- Question 1: total per region -------------------------------------
// Parallel lists again (see project 03) — names in one, totals in the other.
var regionNames = new List<string>();
var regionTotals = new List<decimal>();
foreach (var sale in sales)
{
    bool found = false;
    for (int i = 0; i < regionNames.Count; i++)
    {
        if (regionNames[i] == sale.Region)
        {
            regionTotals[i] = regionTotals[i] + sale.Amount;
            found = true;
            break;
        }
    }
    if (!found)
    {
        regionNames.Add(sale.Region);
        regionTotals.Add(sale.Amount);
    }
}
Console.WriteLine("total per region:");
for (int i = 0; i < regionNames.Count; i++)
{
    Console.WriteLine($"  {regionNames[i]}: {regionTotals[i]:0.00}");
}

// ---- Question 2: top product by revenue --------------------------------
// For each sale, re-sum EVERY sale of the same product (nested loop),
// track the best with flag variables, and keep a "done" list so we don't
// process a product twice.
string topProduct = "";
decimal topRevenue = -1m;
var alreadyDone = new List<string>();
foreach (var sale in sales)
{
    bool done = false;
    foreach (var name in alreadyDone)
    {
        if (name == sale.Product) { done = true; break; }
    }
    if (done) continue;
    alreadyDone.Add(sale.Product);

    decimal revenue = 0m;
    foreach (var other in sales)
    {
        if (other.Product == sale.Product)
        {
            revenue = revenue + other.Amount;
        }
    }
    if (revenue > topRevenue)
    {
        topRevenue = revenue;
        topProduct = sale.Product;
    }
}
Console.WriteLine($"top product: {topProduct} ({topRevenue:0.00})");

// ---- Question 3: average of the big sales (over 100) -------------------
decimal bigSum = 0m;
int bigCount = 0;
foreach (var sale in sales)
{
    if (sale.Amount > 100m)
    {
        bigSum = bigSum + sale.Amount;
        bigCount = bigCount + 1;
    }
}
if (bigCount > 0)
{
    Console.WriteLine($"average of sales over 100: {bigSum / bigCount:0.00}");
}
else
{
    Console.WriteLine("average of sales over 100: (none)");
}

class Sale
{
    public string Product;
    public string Region;
    public decimal Amount;

    public Sale(string product, string region, decimal amount)
    {
        Product = product;
        Region = region;
        Amount = amount;
    }
}

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

// Same data, same three questions as original.cs — the demo only prints.
var sales = new List<Sale>
{
    new("Keyboard", "North", 90m),
    new("Keyboard", "South", 120m),
    new("Mouse",    "North", 40m),
    new("Mouse",    "South", 55m),
    new("Monitor",  "North", 250m),
    new("Monitor",  "West",  300m),
    new("Webcam",   "West",  80m),
    new("Keyboard", "West",  110m),
};

Console.WriteLine("total per region:");
foreach (var (region, total) in SalesReport.TotalByRegion(sales))
{
    Console.WriteLine($"  {region}: {total:0.00}");
}

Console.WriteLine($"top product: {SalesReport.TopProduct(sales)}");
Console.WriteLine($"average of sales over 100: {SalesReport.AverageOver(sales, 100m):0.00}");
Console.WriteLine($"products sold in West: {string.Join(", ", SalesReport.ProductsIn(sales, "West"))}");

// Every question is one pure method, one LINQ pipeline, zero flag variables.
// LINQ is C#'s filter/map/reduce: Where=filter, Select=map, Sum/Average=reduce,
// GroupBy = the thing you hand-rolled with parallel lists in the original.
public static class SalesReport
{
    // "total per region" — GroupBy makes the buckets, ToDictionary labels them.
    public static Dictionary<string, decimal> TotalByRegion(IEnumerable<Sale> sales) =>
        sales.GroupBy(s => s.Region)
             .ToDictionary(g => g.Key, g => g.Sum(s => s.Amount));

    // "top product by revenue" — group, rank the groups, take the winner's name.
    // Throws InvalidOperationException on an empty list (there IS no top product);
    // the tests pin that down.
    public static string TopProduct(IEnumerable<Sale> sales) =>
        sales.GroupBy(s => s.Product)
             .OrderByDescending(g => g.Sum(s => s.Amount))
             .First().Key;

    // "average of the big sales" — filter, project to numbers, average.
    // Returns 0 when nothing qualifies (Average() on empty would throw).
    public static decimal AverageOver(IEnumerable<Sale> sales, decimal threshold)
    {
        var big = sales.Where(s => s.Amount > threshold)
                       .Select(s => s.Amount)
                       .ToList();
        return big.Count == 0 ? 0m : big.Average();
    }

    // Bonus chain: which products sold in a region, de-duplicated, A→Z.
    public static List<string> ProductsIn(IEnumerable<Sale> sales, string region) =>
        sales.Where(s => s.Region == region)
             .Select(s => s.Product)
             .Distinct()
             .OrderBy(p => p)
             .ToList();
}

public static class Tests
{
    static readonly List<Sale> Sample = new()
    {
        new("Keyboard", "North", 90m),
        new("Keyboard", "South", 120m),
        new("Mouse",    "North", 40m),
        new("Mouse",    "South", 55m),
        new("Monitor",  "North", 250m),
        new("Monitor",  "West",  300m),
        new("Webcam",   "West",  80m),
        new("Keyboard", "West",  110m),
    };

    static readonly List<Sale> Empty = new();

    public static int Run()
    {
        Console.WriteLine("TotalByRegion");
        var totals = SalesReport.TotalByRegion(Sample);
        Check.Equal(3, totals.Count, "3 regions in the sample");
        Check.Equal(380m, totals["North"], "North: 90 + 40 + 250");
        Check.Equal(175m, totals["South"], "South: 120 + 55");
        Check.Equal(490m, totals["West"], "West: 300 + 80 + 110");
        Check.Equal(0, SalesReport.TotalByRegion(Empty).Count, "no sales -> empty table (not a crash)");

        Console.WriteLine("TopProduct");
        Check.Equal("Monitor", SalesReport.TopProduct(Sample), "Monitor wins: 550 total revenue");
        Check.Equal("Solo", SalesReport.TopProduct(new List<Sale> { new("Solo", "X", 1m) }),
            "single sale -> that product");
        Check.Throws<InvalidOperationException>(() => SalesReport.TopProduct(Empty),
            "no sales -> throws (there is no top product)");

        Console.WriteLine("AverageOver");
        Check.Equal(195m, SalesReport.AverageOver(Sample, 100m), "(120 + 250 + 300 + 110) / 4");
        Check.Equal(0m, SalesReport.AverageOver(Sample, 1000m), "nothing qualifies -> 0, not a crash");
        Check.Equal(0m, SalesReport.AverageOver(Empty, 0m), "empty list -> 0");
        Check.Equal(130.625m, SalesReport.AverageOver(Sample, 0m), "threshold 0 averages everything");

        Console.WriteLine("ProductsIn");
        var west = SalesReport.ProductsIn(Sample, "West");
        Check.Equal(3, west.Count, "3 distinct products sold in West");
        Check.Equal("Keyboard", west[0], "sorted A->Z: Keyboard first");
        Check.Equal("Webcam", west[2], "sorted A->Z: Webcam last");
        Check.Equal(0, SalesReport.ProductsIn(Sample, "Nowhere").Count, "unknown region -> empty list");

        return Check.Summary();
    }
}
